import json,shlex,subprocess
peers=json.loads(subprocess.check_output(['tailscale','status','--json']))['Peer'];peer=next(p for p in peers.values() if p.get('HostName')=='issachar')
child='''import resource,json,importlib.metadata\nresource.setrlimit(resource.RLIMIT_CPU,(10,10))\nimport mlx.core as mx\nversion=importlib.metadata.version("mlx")\nprevious=mx.set_memory_limit(4*1024*1024)\nprint(json.dumps({"stage":"start","mlx_version":version,"device":str(mx.default_device()),"configured_bytes":4*1024*1024,"previous_limit":previous}),flush=True)\nx=mx.ones((4*1024*1024,),dtype=mx.float32);mx.eval(x)\nprint(json.dumps({"stage":"allocated","array_bytes":16*1024*1024,"active_bytes":mx.get_active_memory(),"cache_bytes":mx.get_cache_memory()}),flush=True)'''
parent='''import subprocess,sys,os\nenv=dict(os.environ);env["PYTHONDONTWRITEBYTECODE"]="1"\ntry:\n r=subprocess.run([sys.executable,"-c",%s],capture_output=True,text=True,timeout=12,env=env)\n print("child_exit",r.returncode);print(r.stdout);print("stderr",r.stderr[-600:])\nexcept subprocess.TimeoutExpired as e:\n print("child_timeout_and_killed",repr(e.stdout))\n'''%repr(child)
cmd=['ssh','-o','BatchMode=yes','-o','ConnectTimeout=6','-o','StrictHostKeyChecking=yes','-o','HostName='+peer['TailscaleIPs'][0],'issachar','python3 -c '+shlex.quote(parent)]
r=subprocess.run(cmd,capture_output=True,text=True,timeout=20);print('ssh_exit',r.returncode);print(r.stdout);print(r.stderr[-500:])
